import java.util.*;
class TeachingShortestPaths { static class E{String to;int w;E(String t,int w){to=t;this.w=w;}} static void dijkstra(){Map<String,List<E>> g=new HashMap<String,List<E>>();g.put("A",Arrays.asList(new E("B",2),new E("C",5)));g.put("B",Arrays.asList(new E("C",1)));g.put("C",new ArrayList<E>());Map<String,Integer>d=new HashMap<String,Integer>();d.put("A",0);d.put("B",999);d.put("C",999);PriorityQueue<String>pq=new PriorityQueue<String>((x,y)->d.get(x)-d.get(y));pq.add("A");while(!pq.isEmpty()){String v=pq.remove();for(E e:g.get(v))if(d.get(v)+e.w<d.get(e.to)){d.put(e.to,d.get(v)+e.w);pq.add(e.to);System.out.println("relax "+v+"->"+e.to+" distance "+d.get(e.to));}}System.out.println(d);System.out.println("Negative-edge counterexample: Dijkstra can finalize a vertex before a later negative edge improves it.");} }
